size(7cm,7cm);

draw(shift(0,0)*yscale(0.6)*Circle((0,0), 1));

draw(shift(1,0)*yscale(0.6)*Circle((0,0), 1));

draw((-2,-1)--(3,-1)--(3,1)--(-2,1)--(-2,-1));

label("A",(-0.5,0));
label("B",(0.5,0));
label("C",(1.5,0));
label("D",(2.3,-0.5));

label("French",(-1.2,0.7));
label("Spanish",(2,0.7));

